mapper.select:
	/*
		StatMapper.selectStatCodeListCount 통계 코드 목록 갯수
	*/
  SELECT COUNT(*) 
  FROM T_TCODE_LIST 
  WHERE DEL_FLAG='N'
	  AND COMPANY_CODE = #{companyCode}

	  AND TABLE_CODE = #{tableCode}

	/*
		StatMapper.selectStatCodeList 통계 코드 목록 조회
	*/
  SELECT TABLE_CODE, TABLE_NAME, COMPANY_CODE, USE_YN, DEL_FLAG 
  FROM T_TCODE_LIST
  WHERE COMPANY_CODE = #{companyCode}

	  AND TABLE_CODE = #{tableCode}

	  AND DEL_FLAG = 'N'
	ORDER BY TABLE_NAME
